begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(16);
select extensions.ok((select bool_and(relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'),'All public tables have RLS');
select extensions.ok(not has_table_privilege('authenticated','public.orders','INSERT'),'No direct order insertion');
select extensions.ok(not has_table_privilege('authenticated','public.orders','UPDATE'),'No direct order updates');
select extensions.ok(not has_table_privilege('authenticated','public.user_roles','INSERT'),'No direct role escalation');
select extensions.ok(not has_table_privilege('authenticated','public.payments','INSERT'),'No client payment insertion');
select extensions.ok(not has_table_privilege('authenticated','public.loyalty_ledger','INSERT'),'No client loyalty mutation');
select extensions.ok(not has_function_privilege('anon','public.nexora_place_order(uuid,jsonb,uuid,text,integer,text,text,uuid)','EXECUTE'),'Anon cannot checkout');
select extensions.ok(not has_function_privilege('authenticated','public.nexora_mark_paid(text,text,bigint,text,jsonb)','EXECUTE'),'Client cannot mark paid');
select extensions.ok(has_function_privilege('service_role','public.nexora_mark_paid(text,text,bigint,text,jsonb)','EXECUTE'),'Provider verification is service-only');
insert into auth.users(id,phone)values('11111111-1111-4111-8111-111111111111','919876543210'),('22222222-2222-4222-8222-222222222222','919876543211');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select extensions.is((select count(*)::integer from public.profiles),1,'Customer sees only own profile');
select extensions.is((select count(*)::integer from public.user_roles),1,'Customer sees only own customer role');
select extensions.is((select count(*)::integer from public.loyalty_accounts),1,'Customer sees own loyalty account');
select extensions.throws_ok($$select public.nexora_admin_setting('cod.enabled','true','test unauthorized')$$,'P0001','Super Admin access required','Customer cannot edit platform settings');
select extensions.throws_ok($$select public.nexora_admin_role('22222222-2222-4222-8222-222222222222','super_admin','test unauthorized')$$,'P0001','Super Admin required','Customer cannot assign roles');
select public.nexora_save_profile('Test Customer','test@example.invalid');
select extensions.is((select full_name from public.profiles where id=auth.uid()),'Test Customer','Own profile can be saved through validated RPC');
select extensions.is((select count(*)::integer from public.admin_audit_logs),0,'Customer cannot read audit logs');
reset role;
select *from extensions.finish();
rollback;
